CompositionLocalProvider(LocalConfiguration provides locale) {
    MonarchTimesheetDiff(
        before = listOf(
                MonarchTimesheetDiffEntry(id = {{submitted.0.id}}, date = {{submitted.0.date|millis}}, minutes = {{submitted.0.minutes}}, project = {{submitted.0.project}}, activity = {{submitted.0.activity}}),
                MonarchTimesheetDiffEntry(id = {{submitted.1.id}}, date = {{submitted.1.date|millis}}, minutes = {{submitted.1.minutes}}, project = {{submitted.1.project}}, billable = {{submitted.1.billable}}),
                MonarchTimesheetDiffEntry(id = {{submitted.2.id}}, date = {{submitted.2.date|millis}}, minutes = {{submitted.2.minutes}}, project = {{submitted.2.project}}),
        ),
        after = listOf(
                MonarchTimesheetDiffEntry(id = {{resubmitted.0.id}}, date = {{resubmitted.0.date|millis}}, minutes = {{resubmitted.0.minutes}}, project = {{resubmitted.0.project}}, activity = {{resubmitted.0.activity}}),
                MonarchTimesheetDiffEntry(id = {{resubmitted.1.id}}, date = {{resubmitted.1.date|millis}}, minutes = {{resubmitted.1.minutes}}, project = {{resubmitted.1.project}}, activity = {{resubmitted.1.activity}}),
                MonarchTimesheetDiffEntry(id = {{resubmitted.2.id}}, date = {{resubmitted.2.date|millis}}, minutes = {{resubmitted.2.minutes}}, project = {{resubmitted.2.project}}, task = {{resubmitted.2.task}}),
        ),
        title = {{title}},
        subtitle = {{subtitle}},
    )
}

examples.setupTemplate:
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

